# ============================================================
# VMRC SOIL MOISTURE DASHBOARD
# ============================================================
#
# This Shiny application displays:
#
# 1. Project and Study ID filters
# 2. Species and growing-season filters
# 3. Two independent treatment comparison panels
# 4. Daily rainfall and vapor pressure deficit (VPD)
# 5. Soil volumetric water content (VWC) profile - Panel A
# 6. Soil volumetric water content (VWC) profile - Panel B
#
# The analytical workflow, database fields, input IDs, output
# IDs, interpolation method, and filtering logic are preserved.
#
# ============================================================


# ============================================================
# STEP 1. LOAD REQUIRED PACKAGES
# ============================================================

library(shiny)
library(readxl)
library(dplyr)


# ============================================================
# STEP 2. LOAD AND PREPARE THE DATA
# ============================================================

soil_data <- readRDS(
  "data/soil_data.rds"
)

soil_data$Date <- as.Date(soil_data$Date)

soil_data$Depth <- suppressWarnings(
  as.numeric(soil_data$Depth)
)

soil_data$VWC <- suppressWarnings(
  as.numeric(soil_data$VWC)
)

soil_data$Rain <- suppressWarnings(
  as.numeric(soil_data$Rain)
)

soil_data$VPD <- suppressWarnings(
  as.numeric(soil_data$VPD)
)
# ------------------------------------------------------------
# Exclude unavailable treatments for CO102 and CO103
# ------------------------------------------------------------
#
# Treatments 1OO and O11 are not available for studies CO102
# and CO103. These study-treatment combinations are removed
# from the dashboard dataset while all other data are retained.
#

soil_data <- soil_data |>
  filter(
    !(
      StudyID %in% c("CO102", "CO103") &
        TRT4 %in% c("1OO", "O11")
    )
  )

# ============================================================
# STEP 3. DASHBOARD AVAILABILITY SETTINGS
# ============================================================

