  "COS",
  "CPT",
  "SPP",
  "SWD"
)

# ------------------------------------------------------------
# Automatically detect available Study IDs
# ------------------------------------------------------------
#
# Study IDs are read directly from the database so newly added
# sites become available without modifying the R script.
# Only Study IDs belonging to the allowed projects are exposed.
