# ============================================================
# STEP 4. INTERPOLATION FUNCTION
# ============================================================

cubic_interp <- function(x, y, xout) {
  
  valid <- is.finite(x) & is.finite(y)
  
  x <- x[valid]
  y <- y[valid]
  
  if (length(x) == 0) {
    return(rep(NA_real_, length(xout)))
  }
  
  ord <- order(x)
  
  x <- x[ord]
  y <- y[ord]
  
  if (anyDuplicated(x)) {
    
    temp <- aggregate(
      y,
      by = list(x = x),
      FUN = mean
    )
    
    x <- temp$x
    y <- temp$x.1
  }
  
  if (length(x) == 1) {
    return(rep(y[1], length(xout)))
  }
  
  if (length(x) == 2) {
    
    return(
      approx(
        x = x,
        y = y,
        xout = xout,
        rule = 2
      )$y
    )
  }
  
  spline_function <- splinefun(
    x = x,
    y = y,
    method = "natural"
  )
  
  xout_limited <- pmin(
    pmax(xout, min(x)),
    max(x)
  )
  
  result <- spline_function(xout_limited)
  
  result[xout < min(x)] <- y[1]
  result[xout > max(x)] <- y[length(y)]
  
  result
}


# ============================================================
# STEP 5. SOIL PROFILE PLOTTING FUNCTION
# ============================================================

make_soil_profile <- function(
    df,
    plot_left = 0.085,
    plot_right = 0.905,
    xaxs_mode = "r",
    shared_xmin = NULL,
    shared_xmax = NULL
) {
  
  df <- df[
    !is.na(df$Date) &
      !is.na(df$Depth) &
      !is.na(df$VWC),
  ]
  
  if (nrow(df) == 0) {
    
    plot.new()
    
    text(
      0.5,
      0.5,
      "No data available for the selected treatment"
    )
    
    return(invisible(NULL))
  }
  
  df$Date_num <- as.numeric(df$Date)
  
  df <- aggregate(
    VWC ~ Date + Date_num + Depth,
    data = df,
    FUN = mean
  )
  
  
  # ----------------------------------------------------------
  # Fixed VWC scale
  # ----------------------------------------------------------
  
  vmin <- 0.10
  vmax <- 0.50
  
  contour_levels <- seq(
    from = vmin,
    to = vmax,
    by = 0.005
  )
  
  
  # ----------------------------------------------------------
  # Color palette
  # ----------------------------------------------------------
  
  anchor_colors <- c(
    "#FF1E00",
    "#FF7A00",
    "#F2C400",
    "#A6E600",
    "#00C800",
    "#1E40D8",
    "#0A0AC8",
    "#14008C",
    "#5A1288"
  )
  
  cols <- colorRampPalette(
    anchor_colors,
    space = "Lab"
  )(
    length(contour_levels) - 1
  )
  
  
  # ----------------------------------------------------------
  # Prepare depth and date values
  # ----------------------------------------------------------
  
  depth_unique <- sort(
    unique(df$Depth)
  )
  
  date_unique <- sort(
    unique(df$Date_num)
  )
  
  sensor_top_unique <- depth_unique
  sensor_bottom_unique <- depth_unique + 40
  
  plot_depth_min <- 0
  
  max_depth_obs <- max(
    depth_unique,
    na.rm = TRUE
  )
  
  plot_depth_max <- max_depth_obs + 40
  
  y_ticks <- seq(
    from = 0,
    to = plot_depth_max,
    by = 40
  )
  
  
  # ==========================================================
  # CASE 1. ONLY ONE SENSOR DEPTH
  # ==========================================================
  
  if (length(depth_unique) == 1) {
    
    df1 <- aggregate(
      VWC ~ Date_num,
      data = df,
      FUN = mean
    )
    
    df1 <- df1[
      order(df1$Date_num),
    ]
    
    if (min(df1$Date_num) == max(df1$Date_num)) {
      
      fine_date <- seq(
        min(df1$Date_num) - 0.5,
        max(df1$Date_num) + 0.5,
        length.out = 700
      )
      
    } else {
      
      fine_date <- seq(
        min(df1$Date_num),
        max(df1$Date_num),
        length.out = 700
      )
    }
    
    fine_vwc <- cubic_interp(
      x = df1$Date_num,
      y = df1$VWC,
      xout = fine_date
    )
    
    fine_vwc[fine_vwc < vmin] <- vmin
    fine_vwc[fine_vwc > vmax] <- vmax
    
    fine_depth <- seq(
      from = plot_depth_min,
      to = plot_depth_max,
      length.out = 400
    )
    
    zfine <- matrix(
      NA_real_,
      nrow = length(fine_depth),
      ncol = length(fine_date)
    )
    
    represented_zone <- (
      fine_depth >= sensor_top_unique[1] &
        fine_depth <= sensor_bottom_unique[1]
    )
    
    zfine[
      represented_zone,
    ] <- matrix(
      rep(
        fine_vwc,
        each = sum(represented_zone)
      ),
      nrow = sum(represented_zone),
      ncol = length(fine_date)
    )
    
    
    # ==========================================================
    # CASE 2. MULTIPLE SENSOR DEPTHS
    # ==========================================================
    
  } else {
    
    full_grid <- expand.grid(
      Date_num = date_unique,
      Depth = depth_unique
    )
    
    df_full <- merge(
      full_grid,
      df[
        ,
        c(
          "Date_num",
          "Depth",
          "VWC"
        )
      ],
      by = c(
        "Date_num",
        "Depth"
      ),
      all.x = TRUE
    )
    
    zmat <- tapply(
      df_full$VWC,
      list(
        df_full$Depth,
        df_full$Date_num
      ),
      mean
    )
    
    depth <- as.numeric(
      rownames(zmat)
    )
    
    date_num <- as.numeric(
      colnames(zmat)
    )
    
    zmat <- as.matrix(zmat)
    
    depth_top <- depth
    depth_bottom <- depth + 40
    
    depth_centers <- ifelse(
      depth == 0,
      35,
      depth + 35
    )
    
    
    # --------------------------------------------------------
    # Temporal interpolation
    # --------------------------------------------------------
    
    if (min(date_num) == max(date_num)) {
      
      fine_date <- seq(
        min(date_num) - 0.5,
        max(date_num) + 0.5,
        length.out = 700
      )
      
    } else {
      
      fine_date <- seq(
        min(date_num),
        max(date_num),
        length.out = 700
      )
    }
    
    z_date <- matrix(
      NA_real_,
      nrow = length(depth),
      ncol = length(fine_date)
    )
    
    for (i in seq_len(nrow(zmat))) {
      
      good <- is.finite(
        zmat[i, ]
      )
      
      if (sum(good) >= 1) {
        
        z_date[i, ] <- cubic_interp(
          x = date_num[good],
          y = zmat[i, good],
          xout = fine_date
        )
      }
    }
    
    z_date[z_date < vmin] <- vmin
    z_date[z_date > vmax] <- vmax
    
    
    # --------------------------------------------------------
    # Vertical interpolation
    # --------------------------------------------------------
    
    fine_depth <- seq(
      from = plot_depth_min,
      to = plot_depth_max,
      length.out = 400
    )
    
    zfine <- matrix(
      NA_real_,
      nrow = length(fine_depth),
      ncol = length(fine_date)
    )
    
    for (j in seq_len(ncol(z_date))) {
      
      good <- is.finite(
        z_date[, j]
      )
      
      if (sum(good) >= 2) {
        
        interp_x <- depth_centers[good]
        interp_y <- z_date[good, j]
        
        if (any(depth[good] == 0)) {
          
          row_depth_zero <- which(
            depth == 0 & good
          )[1]
          
          interp_x <- c(
            0,
            interp_x
          )
          
          interp_y <- c(
            z_date[row_depth_zero, j],
            interp_y
          )
        }
        
        zfine[, j] <- cubic_interp(
          x = interp_x,
          y = interp_y,
          xout = fine_depth
        )
        
      } else if (sum(good) == 1) {
        
        selected_row <- which(good)[1]
        
        represented_zone <- (
          fine_depth >= depth_top[selected_row] &
            fine_depth <= depth_bottom[selected_row]
        )
        
        zfine[
          represented_zone,
          j
        ] <- z_date[selected_row, j]
      }
    }
  }
  
  
  # ----------------------------------------------------------
  # Constrain final values
  # ----------------------------------------------------------
  
  zfine[zfine < vmin] <- vmin
  zfine[zfine > vmax] <- vmax
  
  
  # ==========================================================
  # CREATE QUARTERLY DATE LABELS
  # ==========================================================
  
  min_date <- as.Date(
    min(fine_date),
    origin = "1970-01-01"
  )
  
  max_date <- as.Date(
    max(fine_date),
    origin = "1970-01-01"
  )
  
  start_month <- as.integer(
    format(min_date, "%m")
  )
  
  start_year <- as.integer(
    format(min_date, "%Y")
  )
  
  quarter_start_month <- (
    (start_month - 1) %/% 3
  ) * 3 + 1
  
  first_quarter_date <- as.Date(
    sprintf(
      "%04d-%02d-01",
      start_year,
      quarter_start_month
    )
  )
  
  date_ticks <- seq(
    from = first_quarter_date,
    to = max_date,
    by = "3 months"
  )
  
  date_ticks <- date_ticks[
    date_ticks >= min_date &
      date_ticks <= max_date
  ]
  
  if (length(date_ticks) == 0) {
    date_ticks <- min_date
  }
  
  date_tick_positions <- as.numeric(
    date_ticks
  )
  
  quarter_number <- (
    (
      as.integer(
        format(date_ticks, "%m")
      ) - 1
    ) %/% 3
  ) + 1
  
  date_labels <- paste0(
    "Q",
    quarter_number,
    " ",
    format(date_ticks, "%Y")
  )
  
  
  # ==========================================================
  # DRAW THE SOIL PROFILE
  # ==========================================================
  #
  # The left and right margins match the Rain/VPD plot so the
  # temporal plotting regions align horizontally.
  #
  # ==========================================================
  
  par(
    mar = c(
      3.8,
      4.3,
      0.5,
      7.4
    ),
    mgp = c(
      2.3,
      0.65,
      0
    )
  )
  
  par(
    plt = c(
      plot_left,
      plot_right,
      0.18,
      0.90
    )
  )
  
  image(
    x = fine_date,
    y = fine_depth,
    z = t(zfine),
    col = cols,
    breaks = contour_levels,
    xlab = "",
    ylab = "Soil depth (cm)",
    xlim = c(
      if (is.null(shared_xmin)) min(fine_date) else shared_xmin,
      if (is.null(shared_xmax)) max(fine_date) else shared_xmax
    ),
    ylim = c(
      plot_depth_max,
      plot_depth_min
    ),
    xaxs = xaxs_mode,
    useRaster = TRUE,
    axes = FALSE
  )
  
  visible_contour_levels <- seq(
    from = vmin,
    to = vmax,
    by = 0.025
  )
  
  contour(
    x = fine_date,
    y = fine_depth,
    z = t(zfine),
    levels = visible_contour_levels,
    add = TRUE,
    drawlabels = FALSE,
    col = adjustcolor(
      "white",
      alpha.f = 0.14
    ),
    lwd = 0.20
  )
  
  axis(
    1,
    at = date_tick_positions,
    labels = date_labels,
    las = 1,
    cex.axis = 0.66
  )
  
  axis(
    2,
    at = y_ticks,
    labels = y_ticks,
    las = 1,
    cex.axis = 0.78
  )
  
  mtext(
    "Date",
    side = 1,
    line = 1.8,
    cex = 0.86
  )
  
  box(
    col = "grey40",
    lwd = 0.6
  )
  
  
  # ==========================================================
  # DRAW THE VWC COLOR SCALE
  # ==========================================================
  
  usr <- par("usr")
  
  x_range <- usr[2] - usr[1]
  
  plot_y_min <- min(
    usr[3],
    usr[4]
  )
  
  plot_y_max <- max(
    usr[3],
    usr[4]
  )
  
  y_range <- plot_y_max - plot_y_min
  
  legend_left <- usr[2] + 0.018 * x_range
  legend_right <- usr[2] + 0.040 * x_range
  
  legend_bottom <- plot_y_min + 0.05 * y_range
  legend_top <- plot_y_max - 0.05 * y_range
  
  legend_edges <- seq(
    from = legend_bottom,
    to = legend_top,
    length.out = length(cols) + 1
  )
  
  for (i in seq_along(cols)) {
    
    rect(
      xleft = legend_left,
      ybottom = legend_edges[i],
      xright = legend_right,
      ytop = legend_edges[i + 1],
      col = cols[i],
      border = NA,
      xpd = NA
    )
  }
  
  legend_ticks <- seq(
    from = 0.10,
    to = 0.50,
    by = 0.05
  )
  
  legend_tick_y <- legend_bottom +
    (
      (legend_ticks - vmin) /
        (vmax - vmin)
    ) *
    (
      legend_top - legend_bottom
    )
  
  text(
    x = legend_right + 0.010 * x_range,
    y = legend_tick_y,
    labels = sprintf(
      "%.2f",
      legend_ticks
    ),
    adj = c(
      0,
      0.5
    ),
    cex = 0.66,
    xpd = NA
  )
  
  text(
    x = (
      legend_left +
        legend_right
    ) / 2,
    y = legend_bottom - 0.060 * y_range,
    labels = "VWC (m³/m³)",
    cex = 0.68,
    xpd = NA
  )
}


