# ============================================================
# STEP 7. SERVER LOGIC
# ============================================================

server <- function(input, output, session) {
  
  
  # ==========================================================
  # UPDATE STUDY ID BASED ON PROJECT
  # ==========================================================
  
  observeEvent(
    input$project,
    {
      
      studies <- soil_data |>
        
        filter(
          Project == input$project,
          StudyID %in% allowed_studies
        ) |>
        
        distinct(
          StudyID
        ) |>
        
        arrange(
          StudyID
        ) |>
        
        pull(
          StudyID
        )
      
      updateCheckboxGroupInput(
        session,
        "study",
        choices = studies,
        selected = studies[1]
      )
    }
  )
  
  
  # ==========================================================
  # UPDATE SPECIES
  # ==========================================================
  
  observe({
    
    req(
      input$project,
      input$study
    )
    
    species_choices <- soil_data |>
      
      filter(
        Project == input$project,
        StudyID %in% input$study
      ) |>
      
      distinct(
        Spp2
      ) |>
      
      arrange(
        Spp2
      ) |>
      
      pull(
        Spp2
      )
    
    updateCheckboxGroupInput(
      session,
      "species",
      choices = species_choices,
      selected = species_choices
    )
  })
  
  
  # ==========================================================
  # UPDATE GROWING SEASONS
  # ==========================================================
  
  observe({
    
    req(
      input$project,
      input$study,
      input$species
    )
    
    gs_choices <- soil_data |>
      
      filter(
        Project == input$project,
        StudyID %in% input$study,
        Spp2 %in% input$species
      ) |>
      
      distinct(
        GS
      ) |>
      
      arrange(
        GS
      ) |>
      
      pull(
        GS
      )
    
    updateCheckboxGroupInput(
      session,
      "gs",
      choices = gs_choices,
      selected = gs_choices
    )
  })
  
  
  # ==========================================================
  # UPDATE TREATMENT OPTIONS
  # ==========================================================
  
  observe({
    
    req(
      input$project,
      input$study,
      input$species,
      input$gs
    )
    
    treatment_choices <- soil_data |>
      
      filter(
        Project == input$project,
        StudyID %in% input$study,
        Spp2 %in% input$species,
        GS %in% input$gs
      ) |>
      
      distinct(
        TRT4
      ) |>
      
      arrange(
        TRT4
      ) |>
      
      pull(
        TRT4
      )
    
    updateCheckboxGroupInput(
      session,
      "treatment_a",
      choices = treatment_choices,
      selected = treatment_choices[1]
    )
    
    updateCheckboxGroupInput(
      session,
      "treatment_b",
      choices = treatment_choices,
      selected = if (
        length(treatment_choices) >= 2
      ) {
        treatment_choices[2]
      } else {
        treatment_choices[1]
      }
    )
  })
  
  
  # ==========================================================
  # GENERAL FILTERED DATASET
  # ==========================================================
  
  filtered_general <- reactive({
    
    req(
      input$project,
      input$study,
      input$species,
      input$gs
    )
    
    soil_data |>
      
      filter(
        Project == input$project,
        StudyID %in% input$study,
        Spp2 %in% input$species,
        GS %in% input$gs
      )
  })
  
  
  # ==========================================================
  # FILTERED DATA FOR PANEL A
  # ==========================================================
  
  filtered_panel_a <- reactive({
    
    req(
      input$treatment_a
    )
    
    filtered_general() |>
      
      filter(
        TRT4 %in% input$treatment_a
      )
  })
  
  
  # ==========================================================
  # FILTERED DATA FOR PANEL B
  # ==========================================================
  
  filtered_panel_b <- reactive({
    
    req(
      input$treatment_b
    )
    
    filtered_general() |>
      
      filter(
        TRT4 %in% input$treatment_b
      )
  })
  
  
  # ==========================================================
  # DAILY RAIN AND VPD PLOT
  # ==========================================================
  
  output$rain_vpd_plot <- renderPlot({
    
    df <- filtered_general()
    
    daily <- df |>
      
      group_by(
        Date
      ) |>
      
      summarise(
        Rain = mean(
          Rain,
          na.rm = TRUE
        ),
        VPD = mean(
          VPD,
          na.rm = TRUE
        ),
        .groups = "drop"
      )
    
    daily$Rain[
      !is.finite(daily$Rain)
    ] <- 0
    
    daily$VPD[
      !is.finite(daily$VPD)
    ] <- 0
    
    validate(
      need(
        nrow(daily) > 0,
        "No data available for the selected filters"
      )
    )
    
    daily$Date_num <- as.numeric(
      daily$Date
    )
    
    rain_ylim <- c(
      0,
      100
    )
    
    rain_ticks <- c(
      0,
      25,
      50,
      75,
      100
    )
    
    vpd_ylim <- c(
      0,
      3
    )
    
    vpd_ticks <- c(
      0,
      1,
      2,
      3
    )
    
    date_min_num <- min(
      daily$Date_num,
      na.rm = TRUE
    )
    
    date_max_num <- max(
      daily$Date_num,
      na.rm = TRUE
    )
    
    if (date_min_num == date_max_num) {
      
      date_min_num <- date_min_num - 1
      date_max_num <- date_max_num + 1
    }
    
    
    # --------------------------------------------------------
    # Quarterly labels
    # --------------------------------------------------------
    
    min_date <- min(
      daily$Date,
      na.rm = TRUE
    )
    
    max_date <- max(
      daily$Date,
      na.rm = TRUE
    )
    
    start_month <- as.integer(
      format(
        min_date,
        "%m"
      )
    )
    
    start_year <- as.integer(
      format(
        min_date,
        "%Y"
      )
    )
    
    quarter_start_month <- (
      (start_month - 1) %/% 3
    ) * 3 + 1
    
    first_quarter_date <- as.Date(
      sprintf(
        "%04d-%02d-01",
        start_year,
        quarter_start_month
      )
    )
    
    date_ticks <- seq(
      from = first_quarter_date,
      to = max_date,
      by = "3 months"
    )
    
    date_ticks <- date_ticks[
      date_ticks >= min_date &
        date_ticks <= max_date
    ]
    
    if (length(date_ticks) == 0) {
      date_ticks <- min_date
    }
    
    date_tick_positions <- as.numeric(
      date_ticks
    )
    
    quarter_number <- (
      (
        as.integer(
          format(
            date_ticks,
            "%m"
          )
        ) - 1
      ) %/% 3
    ) + 1
    
    date_labels <- paste0(
      "Q",
      quarter_number,
      " ",
      format(
        date_ticks,
        "%Y"
      )
    )
    
    
    # --------------------------------------------------------
    # Plot appearance
    # --------------------------------------------------------
    
    rain_fill <- "#384393"
    rain_border <- "#384393"
    vpd_color <- "#FF991C"
    
    bar_half_width <- 1.10
    
    par(
      mar = c(
        3.7,
        4.3,
        1.1,
        7.4
      ),
      plt = c(
        0.085,
        0.905,
        0.18,
        0.90
      ),
      mgp = c(
        2.35,
        0.65,
        0
      )
    )
    
    plot(
      NA,
      xlim = c(
        date_min_num,
        date_max_num
      ),
      ylim = rain_ylim,
      xlab = "",
      ylab = "",
      axes = FALSE,
      xaxs = "i",
      yaxs = "i"
    )
    
    abline(
      h = rain_ticks,
      col = "grey88",
      lty = 3,
      lwd = 0.6
    )
    
    valid_rain <- (
      is.finite(daily$Rain) &
        !is.na(daily$Rain)
    )
    
    if (any(valid_rain)) {
      
      rect(
        xleft =
          daily$Date_num[valid_rain] -
          bar_half_width,
        ybottom = 0,
        xright =
          daily$Date_num[valid_rain] +
          bar_half_width,
        ytop = pmin(
          daily$Rain[valid_rain],
          100
        ),
        col = rain_fill,
        border = rain_border,
        lwd = 0.30
      )
    }
    
    axis(
      1,
      at = date_tick_positions,
      labels = date_labels,
      las = 1,
      cex.axis = 0.66
    )
    
    axis(
      2,
      at = rain_ticks,
      labels = rain_ticks,
      las = 1,
      cex.axis = 0.76
    )
    
    mtext(
      "Rain (mm/day)",
      side = 2,
      line = 2.10,
      cex = 0.88
    )
    
    mtext(
      "Date",
      side = 1,
      line = 1.5,
      cex = 0.83
    )
    
    mtext(
      "Date",
      side = 1,
      line = 2.7,
      cex = 0.83
    )
    
    
    # --------------------------------------------------------
    # Secondary VPD axis
    # --------------------------------------------------------
    
    par(
      new = TRUE
    )
    
    plot(
      daily$Date_num,
      daily$VPD,
      type = "l",
      col = vpd_color,
      lwd = 0.65,
      xlim = c(
        date_min_num,
        date_max_num
      ),
      ylim = vpd_ylim,
      xlab = "",
      ylab = "",
      axes = FALSE,
      xaxs = "i",
      yaxs = "i"
    )
    
    axis(
      4,
      at = vpd_ticks,
      labels = vpd_ticks,
      las = 1,
      cex.axis = 0.76
    )
    
    mtext(
      "Mean daily VPD (kPa)",
      side = 4,
      line = 1.9,
      cex = 0.84
    )
    
    box(
      col = "grey40",
      lwd = 0.6
    )
    
    legend(
      "top",
      legend = c(
        "Rain",
        "VPD"
      ),
      pch = c(
        15,
        NA
      ),
      pt.cex = c(
        1.35,
        NA
      ),
      lty = c(
        NA,
        1
      ),
      lwd = c(
        NA,
        0.65
      ),
      col = c(
        rain_fill,
        vpd_color
      ),
      horiz = TRUE,
      bty = "n",
      cex = 0.76
    )
  })
  
  
  # ==========================================================
  # SOIL PROFILE A
  # ==========================================================
  
  output$soil_profile_a <- renderPlot({
    
    make_soil_profile(
      filtered_panel_a(),
      plot_left = 0.085,
      plot_right = 0.905,
      xaxs_mode = "i"
    )
    
  })
  
  
  # ==========================================================
  # SOIL PROFILE B
  # ==========================================================
  
  output$soil_profile_b <- renderPlot({
    
    make_soil_profile(
      filtered_panel_b(),
      plot_left = 0.085,
      plot_right = 0.905,
      xaxs_mode = "i"
    )
    
  }) 
}


